extractions=table('company_business_extractions',ref('parse_id','company_document_parses'),ref('company_id','companies'),ref('file_id','company_files'),Column('kind',String(10),nullable=False),Column('entries',JSONB,nullable=False),UniqueConstraint('parse_id'),UniqueConstraint('id','company_id'),CheckConstraint("kind IN ('finance','history')"),ForeignKeyConstraint(['file_id','company_id'],['company_files.id','company_files.company_id'],ondelete='RESTRICT'))
sources=table('company_business_sources',ref('company_id','companies'),ref('input_version_id','company_input_versions'),ref('extraction_id','company_business_extractions'),ref('evidence_id','company_evidence'),Column('kind',String(10),nullable=False),Column('row_index',Integer,nullable=False),Column('source_index',Integer,nullable=False),Column('field',String(80),nullable=False),Column('original_value',JSONB,nullable=False),Column('saved_value',JSONB,nullable=False),CheckConstraint("kind IN ('finance','history')"),CheckConstraint('row_index>=0 AND source_index>=0'),ForeignKeyConstraint(['input_version_id','company_id'],['company_input_versions.id','company_input_versions.company_id'],ondelete='RESTRICT'),ForeignKeyConstraint(['evidence_id','company_id'],['company_evidence.id','company_evidence.company_id'],ondelete='RESTRICT'),ForeignKeyConstraint(['extraction_id','company_id'],['company_business_extractions.id','company_business_extractions.company_id'],ondelete='RESTRICT'))
