TABLES=(extractions,sources,file_events)

requests=table('company_information_requests',ref('company_id','companies'),ref('input_version_id','company_input_versions',True),ref('improvement_version_id','company_improvement_versions',True),ref('file_id','company_files',True),ref('actor_id','local_actors'),Column('title',String(300),nullable=False),Column('message',Text,nullable=False),Column('due_date',String(10)),Column('state',String(30),nullable=False),Column('response_ordinal',Integer,nullable=False),UniqueConstraint('id','company_id'),CheckConstraint("state IN ('DRAFT','WAITING_RESPONSE','REVIEW_REQUIRED','VERIFIED','REVISION_REQUESTED')"),CheckConstraint('response_ordinal>=0'),ForeignKeyConstraint(['input_version_id','company_id'],['company_input_versions.id','company_input_versions.company_id'],ondelete='RESTRICT'),ForeignKeyConstraint(['file_id','company_id'],['company_files.id','company_files.company_id'],ondelete='RESTRICT'))
